-- Career PR 3a: per-domain state of `job.fetch` (ADR-0008 §4): limiter and circuit breaker, persisted so a
-- restart never resets a quota or an open breaker. Keyed by `jobFetchGroupId` (ICANN eTLD+1); no user data,
-- no URL. Generated by `prisma migrate diff`; plus CHECKs that keep the state sane. The array stays nullable
-- in the DDL (as Prisma models scalar lists) and NOT NULL through a CHECK, so the schema shows no drift.

-- CreateTable
CREATE TABLE "job_fetch_domain_state" (
    "domain" TEXT NOT NULL,
    "last_request_at" TIMESTAMPTZ(3),
    "recent_requests" TIMESTAMPTZ(3)[] DEFAULT ARRAY[]::TIMESTAMPTZ(3)[],
    "breaker_open_until" TIMESTAMPTZ(3),
    "breaker_signal" TEXT,
    "breaker_opened_at" TIMESTAMPTZ(3),
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "job_fetch_domain_state_pkey" PRIMARY KEY ("domain")
);

-- A normalized domain or host (lowercase, no path, no whitespace), never a URL.
ALTER TABLE "job_fetch_domain_state" ADD CONSTRAINT "job_fetch_domain_state_domain_check"
  CHECK (char_length("domain") BETWEEN 1 AND 253 AND "domain" = lower("domain") AND "domain" !~ '[/?#@[:space:]]');
-- The rolling 24 h window holds at most the LinkedIn quota (40); policies may tighten, never loosen.
ALTER TABLE "job_fetch_domain_state" ADD CONSTRAINT "job_fetch_domain_state_recent_requests_check"
  CHECK ("recent_requests" IS NOT NULL AND cardinality("recent_requests") <= 40);
-- `FetchStopSignal`; an open breaker always has its signal and opening instant.
ALTER TABLE "job_fetch_domain_state" ADD CONSTRAINT "job_fetch_domain_state_breaker_check"
  CHECK (
    ("breaker_open_until" IS NULL AND "breaker_signal" IS NULL AND "breaker_opened_at" IS NULL)
    OR ("breaker_open_until" IS NOT NULL AND "breaker_opened_at" IS NOT NULL
        AND "breaker_signal" IS NOT NULL AND "breaker_signal" IN ('http_429', 'http_999', 'http_403', 'login_redirect', 'login_wall'))
  );
